import unittest
def positive(value):
    if value < 0:
        raise ValueError("value must be non-negative")
    return value

class PositiveTests(unittest.TestCase):
    def test_valid(self):
        self.assertEqual(positive(3), 3)
    def test_negative(self):
        with self.assertRaises(ValueError):
            positive(-1)

result = unittest.TextTestRunner(stream=__import__("io").StringIO()).run(unittest.defaultTestLoader.loadTestsFromTestCase(PositiveTests))
print(result.wasSuccessful(), result.testsRun)

